def mri_surf2surf_execute(params: MriSurf2surf, runner: Runner | None = None) -> MriSurf2surfOutputs:
    """
    mri_surf2surf

    Resample one surface onto another using FreeSurfer

    Author: FreeSurfer Developers

    URL: https://github.com/freesurfer/freesurfer

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    mri_surf2surf_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(MRI_SURF2SURF_METADATA)
    execution.params(params)
    args = mri_surf2surf_cargs(params, execution)
    out = mri_surf2surf_outputs(params, execution)
    execution.run(args)
    return out

